use vstd::prelude::*;

verus! {

fn flipud(m: Vec<f32>) -> (result: Vec<f32>)
    ensures
        result.len() == m.len(),
        forall|i: int|
            0 <= i < m.len() ==> result[i] == m[(m.len() - 1 - i) as int],
{
    let n: usize = m.len();
    let mut result: Vec<f32> = Vec::new();

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            result.len() == i,
            // The prefix we have built so far matches the reversed suffix of m
            forall|k: int|
                0 <= k < i ==> result[k] == m[(n - 1 - k) as int],
        decreases n - i,
    {
        // Safe because i < n, so n - 1 - i is within [0, n)
        let idx: usize = n - 1 - i;
        result.push(m[idx]);
        i = i + 1;
    }

    result
}

} // verus!

